{
  "hooks": {
    "PostToolUse": [
      { "matcher": "Edit", "hooks": [ { "type": "command", "command": "pnpm exec prettier --write \"$CLAUDE_FILE_PATH\"" } ] }
    ]
  }
}

{
  "mcpServers": {
    "filesystem": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-filesystem", "/Users/dev/projects/app"]
    },
    "postgres": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-postgres"],
      "env": { "DATABASE_URL": "postgres://localhost:5432/app_dev" }
    }
  }
}

{
  "permissions": {
    "allow": ["Read(./**)", "Bash(pnpm test)", "Bash(git status)"],
    "deny": ["Read(./.env)", "Bash(rm -rf *)"]
  }
}
